-- P1-02 P5 AW21-24 NOR-04/05: inverse normal quantiles and unknown parameters.
-- Critical z-values use standard 4 d.p. conventions; original iClub-authored content only.
begin;
insert into private.exam_prep_content_versions(program_version_id,content_version,component_code,release_label,status,source_policy)
select pv.id,'p5_aw21_24_nor04_05_v1','P5','P5 AW21-24 NOR-04/05 inverse normal and parameters','draft','Original iClub content only; Cambridge 9709 official syllabus defines scope; Complete Probability & Statistics 1 is mapping/teaching reference only; no protected source wording copied. Critical z-values rounded conventionally.'
from private.exam_prep_program_versions pv where pv.program_key='math_as_p1_p5' and pv.version_key='p1_p5_canonical_v1_0'
on conflict(program_version_id,content_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor04_05_v1' and component_code='P5' and status='draft'), src(skill,k,role,diff,qen,qru,quz,o_en,o_ru,o_uz,ans,een,eru,euz,secs) as (values
('P5-NOR-04','P5NOR04-D01','diagnostic','medium','For standard normal Z, P(Z<z)=0.975. Find z to 3 d.p.','Для стандартной нормальной Z, P(Z<z)=0,975. Найдите z до 3 знаков.','Standart normal Z uchun P(Z<z)=0.975. z ni 3 xonagacha toping.','["1.960","-1.960","0.975","0.025"]','["1,960","-1,960","0,975","0,025"]','["1.960","-1.960","0.975","0.025"]','A','The 97.5th percentile of the standard normal distribution is z=1.960.','97,5-й процентиль стандартного normal равен z=1,960.','Standart normalning 97.5-percentili z=1.960.',40),
('P5-NOR-04','P5NOR04-L01','learning','easy','For standard normal Z, find z such that P(Z<z)=0.950.','Для стандартной нормальной Z найдите z, если P(Z<z)=0,950.','Standart normal Z uchun P(Z<z)=0.950 bo‘lsa, z ni toping.','["1.645","1.282","1.960","-1.645"]','["1,645","1,282","1,960","-1,645"]','["1.645","1.282","1.960","-1.645"]','A','The 95th percentile is about 1.6449, conventionally 1.645.','95-й процентиль примерно 1,6449, то есть 1,645.','95-percentil taxminan 1.6449, ya’ni 1.645.',30),
('P5-NOR-04','P5NOR04-L02','learning','medium','Find z such that P(Z>z)=0.10 for standard normal Z.','Найдите z, если P(Z>z)=0,10 для стандартной нормальной Z.','Standart normal Z uchun P(Z>z)=0.10 bo‘lsa, z ni toping.','["1.2816","-1.2816","1.645","0.9000"]','["1,2816","-1,2816","1,645","0,9000"]','["1.2816","-1.2816","1.645","0.9000"]','A','An upper tail of 0.10 means cumulative probability 0.90, whose z-value is 1.2816.','Верхний хвост 0,10 означает накопленную вероятность 0,90, z=1,2816.','Yuqori tail 0.10 bo‘lsa cumulative 0.90, z=1.2816.',35),
('P5-NOR-04','P5NOR04-L03','learning','medium','X~N(50,25). Find the 90th percentile of X to 1 d.p.','X~N(50,25). Найдите 90-й процентиль X до 1 знака.','X~N(50,25). X ning 90-percentilini 1 xonagacha toping.','["56.4","43.6","58.2","51.3"]','["56,4","43,6","58,2","51,3"]','["56.4","43.6","58.2","51.3"]','A','sigma=5 and z_0.90=1.2816, so x=50+5(1.2816)=56.408, giving 56.4.','sigma=5, z_0.90=1,2816, поэтому x=56,408≈56,4.','sigma=5, z_0.90=1.2816, x=56.408≈56.4.',40),
('P5-NOR-04','P5NOR04-R01','retest','easy','For standard normal Z, find z such that P(Z<z)=0.025.','Для стандартной нормальной Z найдите z, если P(Z<z)=0,025.','Standart normal Z uchun P(Z<z)=0.025 bo‘lsa, z ni toping.','["-1.960","1.960","-1.645","-1.282"]','["-1,960","1,960","-1,645","-1,282"]','["-1.960","1.960","-1.645","-1.282"]','A','By symmetry, the 2.5th percentile is -1.960.','По симметрии 2,5-й процентиль равен -1,960.','Simmetriya bo‘yicha 2.5-percentil -1.960.',30),
('P5-NOR-04','P5NOR04-R02','retest','medium','For standard normal Z, the central 90% lies between -z and z. Find z.','Для стандартной нормальной Z центральные 90% лежат между -z и z. Найдите z.','Standart normal Z ning markaziy 90% qismi -z va z orasida. z ni toping.','["1.645","1.282","1.960","0.900"]','["1,645","1,282","1,960","0,900"]','["1.645","1.282","1.960","0.900"]','A','Central 90% leaves 5% in each tail, so the upper boundary is the 95th percentile, z=1.645.','Центральные 90% оставляют по 5% в каждом хвосте, верхняя граница — 95-й процентиль 1,645.','Markaziy 90% har tailda 5% qoldiradi, yuqori chegara 95-percentil 1.645.',35),
('P5-NOR-04','P5NOR04-M01','mixed','medium','X~N(100,16). Find the lower 5th percentile to 1 d.p.','X~N(100,16). Найдите нижний 5-й процентиль до 1 знака.','X~N(100,16). Pastki 5-percentilni 1 xonagacha toping.','["93.4","106.6","92.2","95.0"]','["93,4","106,6","92,2","95,0"]','["93.4","106.6","92.2","95.0"]','A','sigma=4 and z_0.05=-1.645, so x=100-4(1.645)=93.42, giving 93.4.','sigma=4, z_0.05=-1,645, поэтому x=93,42≈93,4.','sigma=4, z_0.05=-1.645, x=93.42≈93.4.',45),

('P5-NOR-05','P5NOR05-D01','diagnostic','medium','X~N(mu,16) and P(X<54)=0.8413. Find mu.','X~N(mu,16) и P(X<54)=0,8413. Найдите mu.','X~N(mu,16) va P(X<54)=0.8413. mu ni toping.','["50","54","58","46"]','["50","54","58","46"]','["50","54","58","46"]','A','0.8413 corresponds to z=1. With sigma=4, (54-mu)/4=1, so mu=50.','0,8413 соответствует z=1. При sigma=4: (54-mu)/4=1, поэтому mu=50.','0.8413 z=1 ga mos. sigma=4: (54-mu)/4=1, demak mu=50.',45),
('P5-NOR-05','P5NOR05-L01','learning','easy','X~N(100,sigma^2) and P(X<110)=0.9772. Find sigma.','X~N(100,sigma^2) и P(X<110)=0,9772. Найдите sigma.','X~N(100,sigma^2) va P(X<110)=0.9772. sigma ni toping.','["5","10","2","20"]','["5","10","2","20"]','["5","10","2","20"]','A','0.9772 corresponds to z=2, so (110-100)/sigma=2 and sigma=5.','0,9772 соответствует z=2, поэтому 10/sigma=2 и sigma=5.','0.9772 z=2 ga mos, 10/sigma=2, sigma=5.',35),
('P5-NOR-05','P5NOR05-L02','learning','medium','X~N(mu,25) and P(X>35)=0.1587. Find mu.','X~N(mu,25) и P(X>35)=0,1587. Найдите mu.','X~N(mu,25) va P(X>35)=0.1587. mu ni toping.','["30","35","40","25"]','["30","35","40","25"]','["30","35","40","25"]','A','Upper tail 0.1587 means 35 is one standard deviation above the mean. sigma=5, so mu=35-5=30.','Верхний хвост 0,1587 означает, что 35 на одно sigma выше среднего. sigma=5, mu=30.','Yuqori tail 0.1587, 35 o‘rtachadan bir sigma yuqori. sigma=5, mu=30.',40),
('P5-NOR-05','P5NOR05-L03','learning','medium','X~N(20,sigma^2) and P(X<14)=0.0228. Find sigma.','X~N(20,sigma^2) и P(X<14)=0,0228. Найдите sigma.','X~N(20,sigma^2) va P(X<14)=0.0228. sigma ni toping.','["3","6","2","12"]','["3","6","2","12"]','["3","6","2","12"]','A','0.0228 corresponds to z=-2. Thus (14-20)/sigma=-2, giving sigma=3.','0,0228 соответствует z=-2. Тогда -6/sigma=-2, sigma=3.','0.0228 z=-2 ga mos. -6/sigma=-2, sigma=3.',40),
('P5-NOR-05','P5NOR05-R01','retest','easy','X~N(mu,9) and P(X<33)=0.8413. Find mu.','X~N(mu,9) и P(X<33)=0,8413. Найдите mu.','X~N(mu,9) va P(X<33)=0.8413. mu ni toping.','["30","33","36","27"]','["30","33","36","27"]','["30","33","36","27"]','A','sigma=3 and z=1, so 33=mu+3 and mu=30.','sigma=3, z=1, поэтому mu=30.','sigma=3, z=1, demak mu=30.',30),
('P5-NOR-05','P5NOR05-R02','retest','medium','X~N(50,sigma^2) and P(X>58)=0.0228. Find sigma.','X~N(50,sigma^2) и P(X>58)=0,0228. Найдите sigma.','X~N(50,sigma^2) va P(X>58)=0.0228. sigma ni toping.','["4","8","2","16"]','["4","8","2","16"]','["4","8","2","16"]','A','Upper tail 0.0228 corresponds to z=2, so 8/sigma=2 and sigma=4.','Верхний хвост 0,0228 соответствует z=2, поэтому sigma=4.','Yuqori tail 0.0228 z=2, 8/sigma=2, sigma=4.',35),
('P5-NOR-05','P5NOR05-M01','mixed','hard','For X~N(mu,sigma^2), P(X<40)=0.1587 and P(X<60)=0.8413. Find mu and sigma.','Для X~N(mu,sigma^2), P(X<40)=0,1587 и P(X<60)=0,8413. Найдите mu и sigma.','X~N(mu,sigma^2) uchun P(X<40)=0.1587 va P(X<60)=0.8413. mu va sigma ni toping.','["mu=50, sigma=10","mu=50, sigma=20","mu=40, sigma=10","mu=60, sigma=10"]','["mu=50, sigma=10","mu=50, sigma=20","mu=40, sigma=10","mu=60, sigma=10"]','["mu=50, sigma=10","mu=50, sigma=20","mu=40, sigma=10","mu=60, sigma=10"]','A','The two probabilities correspond to z=-1 and z=1. Hence 40=mu-sigma and 60=mu+sigma, giving mu=50 and sigma=10.','Вероятности соответствуют z=-1 и z=1. 40=mu-sigma, 60=mu+sigma, поэтому mu=50, sigma=10.','Ehtimollar z=-1 va z=1 ga mos. 40=mu-sigma, 60=mu+sigma, demak mu=50, sigma=10.',55)
)
insert into public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
select 5,'P5 Normal Distribution',s.skill,s.diff,'mcq',s.qen,s.o_en,s.ans,s.een,null,false,s.qru,s.quz,s.qen,s.o_ru,s.o_uz,s.o_en,s.eru,s.euz,s.een,'ExamPrep:P5:p5_aw21_24_nor04_05_v1:'||s.k,s.secs,null,'draft' from cv cross join src s where not exists(select 1 from public.questions q where q.book_ref='ExamPrep:P5:p5_aw21_24_nor04_05_v1:'||s.k);

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor04_05_v1' and status='draft'), keys(skill,k,role) as (values
('P5-NOR-04','P5NOR04-D01','diagnostic'),('P5-NOR-04','P5NOR04-L01','learning'),('P5-NOR-04','P5NOR04-L02','learning'),('P5-NOR-04','P5NOR04-L03','learning'),('P5-NOR-04','P5NOR04-R01','retest'),('P5-NOR-04','P5NOR04-R02','retest'),('P5-NOR-04','P5NOR04-M01','mixed'),
('P5-NOR-05','P5NOR05-D01','diagnostic'),('P5-NOR-05','P5NOR05-L01','learning'),('P5-NOR-05','P5NOR05-L02','learning'),('P5-NOR-05','P5NOR05-L03','learning'),('P5-NOR-05','P5NOR05-R01','retest'),('P5-NOR-05','P5NOR05-R02','retest'),('P5-NOR-05','P5NOR05-M01','mixed'))
insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,k.k,q.id,k.skill,'{}'::text[],k.role,'withheld','draft','Original iClub-authored content; no protected source wording copied.','Authored for p5_aw21_24_nor04_05_v1 from canonical inverse-normal/parameter intent.','Cambridge 9709 2026-2027 v4; P5 5.5 The normal distribution','Complete Probability & Statistics 1; inverse normal and parameter problems (mapping only)','pending','pending','pending','pending','pending',case when k.role='diagnostic' then 'pending' else 'not_applicable' end,md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,''))) from cv cross join keys k join public.questions q on q.book_ref='ExamPrep:P5:p5_aw21_24_nor04_05_v1:'||k.k on conflict(content_version_id,content_key) do nothing;

with meta as (select m.id,m.content_key,m.primary_skill_code from private.exam_prep_question_content_meta m join private.exam_prep_content_versions cv on cv.id=m.content_version_id where cv.content_version='p5_aw21_24_nor04_05_v1' and m.reserve_role='diagnostic'), r(ckey,match,dcode,mtype,fen,fru,fuz,nen,nru,nuz) as (values
('P5NOR04-D01','B','inverse_tail_sign','concept','0.975 is above 0.5, so the quantile must be positive. -1.960 corresponds to cumulative probability 0.025.','0,975 больше 0,5, поэтому квантиль положительный. -1,960 соответствует 0,025.','0.975 0.5 dan katta, kvantil musbat. -1.960 cumulative 0.025 ga mos.','Match the cumulative probability to the side of zero before reading z.','Сначала определите знак z по накопленной вероятности.','Cumulative ehtimolga qarab z ishorasini avval aniqlang.'),
('P5NOR04-D01','C','returns_probability_not_quantile','concept','0.975 is the probability input, not the z-value requested.','0,975 — заданная вероятность, а не искомое z.','0.975 berilgan ehtimol, so‘ralgan z emas.','Use inverse normal to convert probability into a z-value.','Используйте inverse normal для перехода от probability к z.','Probability dan z ga inverse normal bilan o‘ting.'),
('P5NOR04-D01','D','uses_tail_probability_as_z','concept','0.025 is the complementary tail probability, not a standardised coordinate.','0,025 — дополнительная хвостовая вероятность, а не z-координата.','0.025 complementary tail ehtimoli, z-koordinata emas.','Keep probability and z on different scales.','Не смешивайте probability и z.','Probability va z ni aralashtirmang.'),
('P5NOR05-D01','B','sets_mu_equal_cutoff','concept','The cutoff 54 is one standard deviation above the mean, not the mean itself.','Граница 54 находится на одно sigma выше среднего, а не равна среднему.','54 chegara o‘rtachadan bir sigma yuqori, o‘rtachaning o‘zi emas.','Convert the probability to z before solving for mu.','Сначала преобразуйте probability в z, затем решайте относительно mu.','Avval probability ni z ga aylantirib, keyin mu ni toping.'),
('P5NOR05-D01','C','wrong_direction_from_z','method','z=1 means cutoff=mu+sigma=mu+4. Thus mu=50, not 58.','z=1 означает cutoff=mu+4, поэтому mu=50, не 58.','z=1 cutoff=mu+4, demak mu=50, 58 emas.','Write x=mu+z sigma explicitly.','Запишите x=mu+z sigma.','x=mu+z sigma ni aniq yozing.'),
('P5NOR05-D01','D','uses_double_sigma','method','46 would place 54 two standard deviations above the mean, giving cumulative probability about 0.9772, not 0.8413.','При mu=46 граница 54 была бы на 2 sigma выше среднего, что даёт около 0,9772.','mu=46 bo‘lsa 54 o‘rtachadan 2 sigma yuqori bo‘ladi, ehtimol 0.9772 atrofida.','Check the implied z after solving.','После решения проверьте получившееся z.','Yechgach hosil bo‘lgan z ni tekshiring.'))
insert into private.exam_prep_diagnostic_rules(content_meta_id,rule_version,answer_kind,answer_match,distractor_code,mistake_type,weak_skill_code,feedback_en,feedback_ru,feedback_uz,next_action_en,next_action_ru,next_action_uz,status,approved_at)
select meta.id,'drv1','mcq_option',r.match,r.dcode,r.mtype,meta.primary_skill_code,r.fen,r.fru,r.fuz,r.nen,r.nru,r.nuz,'approved',now() from r join meta on meta.content_key=r.ckey on conflict(content_meta_id,rule_version,answer_kind,answer_match) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor04_05_v1' and status='draft'), defs(task_key,skill,en,ru,uz,rubric,sen,sru,suz) as (values
('P5NOR04-W01','P5-NOR-04','Let X~N(70,9). Find the 95th percentile, the lower 2.5th percentile, and the central 80% interval for X. Give endpoints to 1 d.p. and state the z-values used.','Пусть X~N(70,9). Найдите 95-й процентиль, нижний 2,5-й процентиль и центральный 80%-интервал для X. Дайте границы до 1 знака и укажите использованные z.','X~N(70,9). X ning 95-percentili, pastki 2.5-percentili va markaziy 80% intervalini toping. Chegaralarni 1 xonagacha va ishlatilgan z larni yozing.','{"max_marks":12,"criteria":[{"id":"sigma","marks":1,"rule":"Uses sigma=3."},{"id":"p95","marks":3,"rule":"Uses z=1.645 and gets 74.9."},{"id":"p025","marks":3,"rule":"Uses z=-1.960 and gets 64.1."},{"id":"central_z","marks":2,"rule":"Uses z=+-1.2816 for 10% tails."},{"id":"central_interval","marks":3,"rule":"Gets approximately [66.2,73.8]."}]}','Translate each percentile/tail statement into a cumulative probability first; then apply x=mu+z sigma.','Сначала переведите каждое условие в накопленную probability; затем используйте x=mu+z sigma.','Har bir percentile/tail shartini avval cumulative probability ga aylantiring; keyin x=mu+z sigma ishlating.'),
('P5NOR05-W01','P5-NOR-05','For X~N(mu,sigma^2), P(X<84)=0.1587 and P(X<108)=0.8413. Find mu and sigma. Then, separately, Y~N(mu,25) has 90th percentile 76.4; estimate mu to 1 d.p. using z_0.90=1.2816.','Для X~N(mu,sigma^2), P(X<84)=0,1587 и P(X<108)=0,8413. Найдите mu и sigma. Затем отдельно: Y~N(mu,25) имеет 90-й процентиль 76,4; оцените mu до 1 знака, используя z_0.90=1,2816.','X~N(mu,sigma^2) uchun P(X<84)=0.1587 va P(X<108)=0.8413. mu va sigma ni toping. So‘ng alohida Y~N(mu,25) ning 90-percentili 76.4; z_0.90=1.2816 bilan mu ni 1 xonagacha toping.','{"max_marks":12,"criteria":[{"id":"z_pair","marks":2,"rule":"Maps probabilities to z=-1 and z=1."},{"id":"equations","marks":2,"rule":"Forms 84=mu-sigma and 108=mu+sigma."},{"id":"parameters","marks":3,"rule":"Gets mu=96 and sigma=12."},{"id":"second_setup","marks":2,"rule":"Uses 76.4=mu+5(1.2816)."},{"id":"second_mu","marks":3,"rule":"Gets mu approximately 70.0."}]}','When two quantiles are given, turn each into a linear equation in mu and sigma; solve the pair before substituting back.','При двух квантилях составьте два линейных уравнения для mu и sigma и решите систему.','Ikki kvantil berilsa, mu va sigma uchun ikki chiziqli tenglama tuzib yeching.'))
insert into private.exam_prep_written_tasks(content_version_id,task_key,component_code,primary_skill_code,task_version,prompt_en,prompt_ru,prompt_uz,rubric_json,self_review_en,self_review_ru,self_review_uz,lifecycle_state,copyright_status,qa_math_status,qa_language_status,qa_technical_status,approved_at)
